def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "u": 3, "^": 4}

    def apply() -> bool:
        op = operators.pop()

        if op == "u":
            values[-1] = -values[-1]
            return True

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                return False
            result = a ** b
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)
        return True

    i = 0
    expecting_operand = True

    while i < len(expr):
        char = expr[i]

        if char == " ":
            i += 1
            continue

        if "0" <= char <= "9":
            # Avoid Python's limit on decimal string-to-int conversion.
            number = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                number = number * 10 + ord(expr[i]) - ord("0")
                i += 1
            values.append(number)
            expecting_operand = False
            continue

        if char == "(":
            operators.append(char)
            expecting_operand = True
        elif char == ")":
            while operators[-1] != "(":
                if not apply():
                    return "error"
            operators.pop()
            expecting_operand = False
        elif char == "-" and expecting_operand:
            # A prefix operator never pops a pending power operator.
            operators.append("u")
        else:
            while operators and operators[-1] != "(":
                top_priority = precedence[operators[-1]]
                current_priority = precedence[char]
                if top_priority < current_priority:
                    break
                if top_priority == current_priority and char == "^":
                    break
                if not apply():
                    return "error"
            operators.append(char)
            expecting_operand = True

        i += 1

    while operators:
        if not apply():
            return "error"

    return values[0]
